package de.pulselibre

import android.content.Context
import android.widget.ImageView
import androidx.annotation.DrawableRes

/** PulsLibre icon system v1 (design/icons/v1): vector drawables generated by tools/svg_icons_to_vector.py. */
internal enum class PlIcon(@DrawableRes val res: Int, val label: String) {
    AGE(R.drawable.ic_pl_age, "Alter"),
    BMI(R.drawable.ic_pl_bmi, "BMI"),
    HEIGHT(R.drawable.ic_pl_height, "Größe"),
    PROFILE(R.drawable.ic_pl_profile, "Profil"),
    WEIGHT(R.drawable.ic_pl_weight, "Gewicht"),
    BAND_TIME(R.drawable.ic_pl_band_time, "Uhrzeit des Bands"),
    BATTERY(R.drawable.ic_pl_battery, "Akku"),
    BODY_BATTERY(R.drawable.ic_pl_body_battery, "Body Battery"),
    BREATHING(R.drawable.ic_pl_breathing, "Atmung"),
    CALENDAR(R.drawable.ic_pl_calendar, "Kalender"),
    CALORIES(R.drawable.ic_pl_calories, "Kalorien"),
    CIRQA_BAND(R.drawable.ic_pl_cirqa_band, "CIRQA-Band"),
    CONSISTENCY(R.drawable.ic_pl_consistency, "Aktivitätskonstanz"),
    DATA(R.drawable.ic_pl_data, "Daten"),
    DEVICE(R.drawable.ic_pl_device, "Gerät"),
    FIRMWARE(R.drawable.ic_pl_firmware, "Firmware"),
    FITNESS(R.drawable.ic_pl_fitness, "Fitnessentwicklung"),
    HEART(R.drawable.ic_pl_heart, "Herzfrequenz"),
    HISTORY(R.drawable.ic_pl_history, "Verlauf"),
    HOURGLASS(R.drawable.ic_pl_hourglass, "Datenabdeckung"),
    IDENTITY(R.drawable.ic_pl_identity, "Modell und Seriennummer"),
    INFO(R.drawable.ic_pl_info, "Information"),
    INTENSITY(R.drawable.ic_pl_intensity, "Intensität"),
    OVERVIEW(R.drawable.ic_pl_overview, "Übersicht"),
    OXYGEN(R.drawable.ic_pl_oxygen, "SpO₂"),
    RECORD_START(R.drawable.ic_pl_record_start, "Aufzeichnung starten"),
    RECORD_STOP(R.drawable.ic_pl_record_stop, "Aufzeichnung stoppen"),
    RECOVERY(R.drawable.ic_pl_recovery, "Regeneration"),
    RR_INTERVAL(R.drawable.ic_pl_rr_interval, "RR-Intervall"),
    SESSIONS(R.drawable.ic_pl_sessions, "Sitzungen"),
    SIGNAL(R.drawable.ic_pl_signal, "Empfang"),
    STEPS(R.drawable.ic_pl_steps, "Schritte"),
    STORAGE(R.drawable.ic_pl_storage, "Speicher"),
    STRESS(R.drawable.ic_pl_stress, "Stress"),
    TESTLAB(R.drawable.ic_pl_testlab, "Testlabor"),
    TREND_LINK(R.drawable.ic_pl_trend_link, "Zusammenhang"),
    TRENDS(R.drawable.ic_pl_trends, "Trends");

    companion object {
        /** Icon as a sized drawable for compound drawables (text rows); [tint] flattens colours, null keeps the theme colours. */
        fun drawable(context: Context, icon: PlIcon, sizeDp: Int, tint: Int? = null): android.graphics.drawable.Drawable {
            val px = (sizeDp * context.resources.displayMetrics.density + 0.5f).toInt()
            val d = androidx.core.content.ContextCompat.getDrawable(context, icon.res)!!.mutate()
            d.setBounds(0, 0, px, px)
            if (tint != null) d.setTint(tint)
            return d
        }

        /** Icon as a view. [tint] flattens all colours (navigation states); null keeps the two-tone theme colours. */
        fun view(context: Context, icon: PlIcon, sizeDp: Int, tint: Int? = null, describe: Boolean = false): ImageView =
            ImageView(context).apply {
                setImageResource(icon.res)
                scaleType = ImageView.ScaleType.FIT_CENTER
                layoutParams = android.view.ViewGroup.LayoutParams((sizeDp * resources.displayMetrics.density + 0.5f).toInt(), (sizeDp * resources.displayMetrics.density + 0.5f).toInt())
                if (tint != null) setColorFilter(tint)
                if (describe) contentDescription = icon.label else importantForAccessibility = android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO
            }
    }
}
